<script setup lang="ts">
import {localize} from './localization';

import {computed,ref,watch,nextTick} from 'vue';
import {useSession} from './store';
const props=defineProps<{language:'zh'|'en';picked?:{faceId:string;vertexId:string};targetId?:string}>(),store=useSession(),zh=computed(()=>props.language==='zh');
const faceIndex=ref(1),startId=ref(''),endId=ref('');
const fraction=ref(.5);
const mesh=computed(()=>store.data.project?.surface),face=computed(()=>mesh.value?.faces[faceIndex.value-1]);
const points=computed(()=>face.value?.vertices.map(id=>mesh.value!.vertices.find(v=>v.id===id)!)??[]);
watch(face,f=>{startId.value=f?.vertices[0]??'';endId.value=f?.vertices[1]??'';},{immediate:true});
watch(()=>props.picked,async value=>{if(!value||!mesh.value)return;faceIndex.value=mesh.value.faces.findIndex(f=>f.id===value.faceId)+1;await nextTick();startId.value=value.vertexId;endId.value=face.value?.vertices.find(id=>id!==value.vertexId)??'';});
function edit(index:number){const edge=mesh.value?.cutConstraints?.[index];if(!edge||!mesh.value)return;faceIndex.value=mesh.value.faces.findIndex(f=>f.vertices.includes(edge.a)&&f.vertices.includes(edge.b))+1;void nextTick(()=>{startId.value=edge.a;endId.value=edge.b;});}
watch(()=>props.targetId,id=>{if(!id?.startsWith('cut:'))return;const index=mesh.value?.cutConstraints?.findIndex(edge=>'cut:'+edge.a+':'+edge.b===id)??-1;if(index>=0)edit(index);},{immediate:true});
async function add(){const p=store.data.project,s=mesh.value;if(!p||!s||!startId.value||!endId.value||startId.value===endId.value)return;const edges=(s.cutConstraints??[]).filter(e=>[e.a,e.b].sort().join(':')!==[startId.value,endId.value].sort().join(':'));await store.run(()=>window.fpcad.apply(p.id,p.revision,{type:'surface.set',surface:{...JSON.parse(JSON.stringify(s)),cutConstraints:[...edges,{a:startId.value,b:endId.value,locked:true}]}}));}
async function remove(index:number){const p=store.data.project,s=mesh.value;if(p&&s)await store.run(()=>window.fpcad.apply(p.id,p.revision,{type:'surface.set',surface:{...JSON.parse(JSON.stringify(s)),cutConstraints:s.cutConstraints?.filter((_,i)=>i!==index)}}));}
async function split(){const p=store.data.project,s=mesh.value;if(!p||!s)return;const previous=new Set(s.vertices.map(v=>v.id));if(!await store.run(()=>window.fpcad.apply(p.id,p.revision,{type:'surface.split',a:startId.value,b:endId.value,t:fraction.value})))return;const inserted=mesh.value?.vertices.find(v=>!previous.has(v.id));if(!inserted)return;faceIndex.value=mesh.value!.faces.findIndex(f=>f.vertices.includes(inserted.id))+1;await nextTick();startId.value=inserted.id;endId.value=face.value!.vertices.find(id=>id!==inserted.id)!;}
</script>
<template><details v-if="mesh" class="cut-lines" open><summary>{{zh?'手动切分点与切分线':localize('Manual cut points and lines')}}</summary><p>{{zh?'选择边的两个端点，可以在边上插入新切分点，再添加切分线。也可点选模型区域并锁定边界。修改后重新计算右侧预览。':localize('Choose a triangle and two edge endpoints to add a locked cut. Region selection can lock a whole boundary. Recompute the right preview after changes.')}}</p><label>{{zh?'三角面编号':localize('Triangle number')}}<input type="number" v-model.number="faceIndex" min="1" :max="mesh.faces.length"></label><div class="two-col"><label>{{zh?'起始切分点':localize('Start point')}}<select v-model="startId"><option v-for="(p,i) in points" :key="p.id" :value="p.id">{{i+1}} · {{p.xMm.toFixed(1)}}, {{p.yMm.toFixed(1)}}, {{p.zMm.toFixed(1)}} mm</option></select></label><label>{{zh?'终止切分点':localize('End point')}}<select v-model="endId"><option v-for="(p,i) in points" :key="p.id" :value="p.id">{{i+1}} · {{p.xMm.toFixed(1)}}, {{p.yMm.toFixed(1)}}, {{p.zMm.toFixed(1)}} mm</option></select></label></div><div class="insert-cut-point"><label>{{zh?'新点在边上的位置（0～1）':localize('Position along edge (0–1)')}}<input v-model.number="fraction" type="number" min=".01" max=".99" step=".01" aria-label="切分点位置"></label><button :disabled="store.busy||!face||startId===endId||fraction<=0||fraction>=1" @click="split">{{zh?'在边上新增切分点':localize('Insert point on edge')}}</button></div><button :disabled="store.busy||!face||startId===endId" @click="add">{{zh?'新增切分线':localize('Add cut line')}}</button><div v-for="(edge,i) in mesh.cutConstraints??[]" :key="edge.a+edge.b" class="saved-cut"><small>{{i+1}} · {{edge.a.slice(0,6)}} → {{edge.b.slice(0,6)}}</small><button :disabled="store.busy" @click="edit(i)">{{zh?'调整点位':localize('Edit points')}}</button><button :disabled="store.busy" @click="remove(i)">{{zh?'删除':localize('Delete')}}</button></div></details></template>
<style scoped>.cut-lines{padding:15px;border-block:1px solid var(--border)}summary{font-size:12px;cursor:pointer}.cut-lines p{font-size:11px;color:var(--accent)}.cut-lines label{font-size:11px;margin:10px 0}.cut-lines select{font-size:10px}.saved-cut{display:flex;justify-content:space-between;align-items:center;margin-top:6px}.saved-cut button{padding:3px 7px;font-size:10px}</style>
